import {T,V,clamp,unit,rng} from './math.js';
import {G,M,buildModel,mergeParts} from './models.js';
import {canvas,texture} from './textures.js';
const matrix=new T.Matrix4(),quat=new T.Quaternion(),one=V(1,1,1),yaxis=V(0,1,0),color=new T.Color();
export class Effects {
 constructor(scene){this.scene=scene;this.random=rng(175);this.parts=Array.from({length:384},()=>({p:V(),v:V(),life:0,max:1,c:new T.Color()}));this.at=0;this.positions=new Float32Array(384*3);this.colors=new Float32Array(384*3);const geom=new T.BufferGeometry();geom.setAttribute('position',new T.BufferAttribute(this.positions,3).setUsage(T.DynamicDrawUsage));geom.setAttribute('color',new T.BufferAttribute(this.colors,3).setUsage(T.DynamicDrawUsage));const c=canvas(32),x=c.getContext('2d'),grad=x.createRadialGradient(16,16,0,16,16,16);grad.addColorStop(0,'white');grad.addColorStop(.2,'rgba(255,255,255,.8)');grad.addColorStop(1,'rgba(255,255,255,0)');x.fillStyle=grad;x.fillRect(0,0,32,32);this.particleTexture=texture(c);this.points=new T.Points(geom,new T.PointsMaterial({map:this.particleTexture,color:0xffffff,vertexColors:true,size:.22,transparent:true,depthWrite:false,blending:T.AdditiveBlending}));this.points.frustumCulled=false;scene.add(this.points);
  this.beamGeometry=new T.CylinderGeometry(1,1,1,6,1,true);this.beams=this.batch(this.beamGeometry,2048);this.orbs=this.batch(G.sphere,1300);this.rings=this.batch(G.torus,96);this.shards=this.batch(G.oct,1800);this.health=this.batch(G.box,512);this.pulses=[];this.debris=Array.from({length:96},()=>({p:V(),v:V(),life:0,phase:0,scale:V(),color:0x7797ac}));this.debrisAt=0;this.debrisBatch=this.batch(G.box,96);this.missileParts=mergeParts(buildModel('missilePickup')).map(part=>{const mesh=new T.InstancedMesh(part.geometry,part.material,256);mesh.instanceMatrix.setUsage(T.DynamicDrawUsage);mesh.frustumCulled=false;mesh.count=0;scene.add(mesh);return {...part,mesh};});
 }
 batch(geo,n){const mat=new T.MeshBasicMaterial({color:0xffffff,toneMapped:false}),b=new T.InstancedMesh(geo,mat,n);b.instanceMatrix.setUsage(T.DynamicDrawUsage);b.frustumCulled=false;b.count=0;this.scene.add(b);return b;}
 instance(batch,index,pos,scale,c,rotation=new T.Quaternion()){if(index>=batch.instanceMatrix.count)return index;matrix.compose(pos,rotation,scale);batch.setMatrixAt(index,matrix);batch.setColorAt(index,color.set(c));return index+1;}
 beam(a,b,width,c,index){const dir=b.clone().sub(a),len=dir.length();quat.setFromUnitVectors(yaxis,dir.normalize());return this.instance(this.beams,index,a.clone().add(b).multiplyScalar(.5),V(width,len,width),c,quat);}
 event(e){if(!e.p)return;if(e.type==='break')for(let i=0;i<3;i++){const d=this.debris[this.debrisAt++%96];d.p.copy(e.p);d.v.copy(unit(this.random)).multiplyScalar(2+this.random()*3);d.life=1.3+this.random()*.4;d.phase=this.random()*6;d.scale.set(.14+this.random()*.26,.08+this.random()*.14,.15+this.random()*.3);d.color=e.kind==='crate'?0xa0815e:0x8aa6b9;}const n=['boom','break','warp'].includes(e.type)?14:['hit','impact','slash'].includes(e.type)?5:0;for(let i=0;i<n;i++){const p=this.parts[this.at++%384];p.p.copy(e.p);p.v.copy(unit(this.random)).multiplyScalar(2+this.random()*6);p.max=p.life=.25+this.random()*.65;p.c.set(e.color||(['boom','break'].includes(e.type)?0xffbf74:0x81efff));}if(['pulse','boom','warp'].includes(e.type)&&this.pulses.length<24)this.pulses.push({p:e.p.clone(),age:0,life:e.type==='pulse'?.55:.4,r:e.radius||2,color:e.type==='pulse'?0x83e8ff:0xffd3a0});}
 update(g,dt,camera){let pn=0;for(const p of this.parts){p.life-=dt;if(p.life<=0)continue;p.p.addScaledVector(p.v,dt);p.v.multiplyScalar(Math.exp(-2*dt));p.p.toArray(this.positions,pn*3);color.copy(p.c).multiplyScalar(p.life/p.max).toArray(this.colors,pn*3);pn++;}this.points.geometry.setDrawRange(0,pn);this.points.geometry.attributes.position.needsUpdate=true;this.points.geometry.attributes.color.needsUpdate=true;
  let bn=0,on=0,rn=0,sn=0,hn=0,mn=0,dn=0;const w=g.weapons;for(const b of [w.beam,w.goldBeam])if(b)bn=this.beam(b.a,b.b,b.width,b.color,bn);
  for(const id of w.lasso){const e=g.entities.find(e=>e.id===id&&e.alive);if(e){bn=this.beam(w.tip,e.p,.018,0xff6989,bn);rn=this.instance(this.rings,rn,e.p,V(e.r*1.3,e.r*1.3,e.r*1.3),0xff647e);}}
  if(w.charge>0){const t=clamp(w.charge/(7.170193/g.power),0,1),r=.045+t*.28;on=this.instance(this.orbs,on,w.muzzle,V(r,r,r),g.player.gold>0?0xffdc6b:0x8ffff0);rn=this.instance(this.rings,rn,w.muzzle,V(r*1.2,r*1.2,r*1.2),0xb98bff,quat.setFromAxisAngle(yaxis,g.time*4));}
  for(const stroke of g.strokes)for(let i=1;i<stroke.points.length;i++)bn=this.beam(stroke.points[i-1],stroke.points[i],stroke.solid?.065:.04,stroke.solid?0xd4a0ff:0x63fff0,bn);
  for(const b of g.projectiles){const bright=b.kind==='hydraplasma'?0xd99bff:b.color||(b.owner==='enemy'?0xff795e:0x9cfff0);const r=b.r*(b.kind==='plasma'?1.05:1);if(b.kind==='missile'||b.kind==='rocket'){if(mn<256){matrix.compose(b.p,new T.Quaternion().setFromUnitVectors(V(0,0,1),b.v.clone().normalize()),V(.5,.5,.5));for(const p of this.missileParts)p.mesh.setMatrixAt(mn,matrix);mn++;}}else on=this.instance(this.orbs,on,b.p,V(r,r,r),bright);bn=this.beam(b.p,b.p.clone().addScaledVector(b.v,-.035),Math.min(.055,r*.3),bright,bn);}
  for(const e of g.entities){if(!e.alive)continue;const distance=e.p.distanceTo(g.player.p);if(e.item&&distance<65){const type=e.type,scale=type==='gold'?.55:type==='missilePickup'?0:.16;if(!scale)continue;const c=type==='gold'?0xffdc76:type==='coin'?0xeab461:0x83efde;sn=this.instance(this.shards,sn,e.p,V(scale,scale*1.4,scale),c,quat.setFromAxisAngle(yaxis,g.time*.7+e.phase));}
   if(e.type==='well'&&distance<80)for(let i=0;i<3;i++){const q=new T.Quaternion().setFromEuler(new T.Euler(i===0?Math.PI/2:0,i===1?Math.PI/2:0,g.time*.08));rn=this.instance(this.rings,rn,e.p,V(e.r,e.r,e.r),0x386e85,q);}
   if(e.type==='hydra'&&e.charge>0&&e.mouth){const r=.07+e.charge*.25;on=this.instance(this.orbs,on,e.mouth,V(r,r,r),0xe3baff);rn=this.instance(this.rings,rn,e.mouth,V(r*1.6,r*1.6,r*1.6),0xb167ff,quat.setFromAxisAngle(yaxis,g.time*7));}
   if(e.beamT>0&&distance<100){const a=e.mouth||e.p,b=a.clone().addScaledVector(e.beamDir||e.dir,45),hit=g.map.ray(a,e.beamDir||e.dir,45);if(hit)b.copy(hit.pos);bn=this.beam(a,b,.08,e.type==='hydra'?0xb778ed:0xff694a,bn);}
   if((e.enemy||e.type==='pet'||e.type==='kennel')&&distance<40){const hp=clamp(e.hp/e.maxHp,0,1),pos=e.p.clone().add(V(0,e.r+.45,0)),q=camera.getWorldQuaternion(new T.Quaternion());hn=this.instance(this.health,hn,pos,V(1.0,.06,.015),0x301f33,q);pos.add(V((hp-1)*.48,0,.02).applyQuaternion(q));hn=this.instance(this.health,hn,pos,V(hp*.96,.044,.02),e.type==='pet'?0x71eac6:0xffaa7f,q);}
  }
  for(const rift of g.rifts){if(rift.life<=0||rift.p.distanceToSquared(g.player.p)>10000)continue;const r=1.1+Math.min(1,rift.age)*.6;rn=this.instance(this.rings,rn,rift.p,V(r,r,r),rift.released?0x568594:0xffbe77,new T.Quaternion().setFromUnitVectors(V(0,0,1),rift.dir));}
  for(const p of this.pulses){p.age+=dt;if(p.age>=p.life)continue;const r=Math.max(.01,p.r*p.age/p.life),t=1-p.age/p.life;rn=this.instance(this.rings,rn,p.p,V(r,r,r),color.set(p.color).multiplyScalar(t));}this.pulses=this.pulses.filter(p=>p.age<p.life);
  for(const d of this.debris){d.life-=dt;if(d.life<=0)continue;d.p.addScaledVector(d.v,dt);d.v.multiplyScalar(Math.exp(-.7*dt));const size=d.scale.clone().multiplyScalar(Math.min(1,d.life*3));dn=this.instance(this.debrisBatch,dn,d.p,size,d.color,new T.Quaternion().setFromEuler(new T.Euler(g.time*2+d.phase,g.time+d.phase,0)));}for(const p of this.missileParts){p.mesh.count=mn;p.mesh.visible=mn>0;p.mesh.instanceMatrix.needsUpdate=true;}
  for(const [b,n]of [[this.debrisBatch,dn],[this.beams,bn],[this.orbs,on],[this.rings,rn],[this.shards,sn],[this.health,hn]]){b.count=n;b.visible=n>0;b.instanceMatrix.needsUpdate=true;if(b.instanceColor)b.instanceColor.needsUpdate=true;}
 }
 dispose(){for(const b of [this.debrisBatch,this.beams,this.orbs,this.rings,this.shards,this.health]){this.scene.remove(b);b.dispose();b.material.dispose();}this.scene.remove(this.points);this.points.geometry.dispose();this.points.material.dispose();this.particleTexture.dispose();this.beamGeometry.dispose();for(const p of this.missileParts){this.scene.remove(p.mesh);p.mesh.dispose();p.geometry.dispose();}}
}
